import{p as o,b as e,C as s}from"./vue-vendor-de6b2611.js";const n={class:"markdown-body"},p=s('<h1>R1 产品文档</h1><h2>硬件设计</h2><p><img src="https://s2.loli.net/2023/03/18/8kR6c5wLIAbF2ox.jpg" alt="R1 硬件设计"></p><blockquote><p>从零到一，独家设计。因商务合作关系，部分消费者可能会看到其他冠名的产品 <em>(非硬酷渠道产品，不享受本公司售后)</em>。</p></blockquote><ul><li><strong>CPU：</strong> 赛扬 N5105、奔腾银牌 N6005</li><li><strong>内存：</strong> LPDDR4 双通道，单颗粒 8GB（<strong><code>16GB 为双内存颗粒双通道</code></strong>）</li><li><strong>网卡：</strong> 4 x Intel i226-V</li><li><strong>硬盘：</strong> 1 x <strong>M.2 2242 NVMe（PCIe 3.0 x2 速率）</strong></li><li><strong>显示：</strong> 1 x HDMI 2.0，支持 4K 60Hz 视频输出</li><li><strong>USB：</strong> 2 x USB 3.1 Gen2，1 x USB-C 3.1 Gen2</li><li><strong>TF 卡：</strong> 1 x TF Card Reader，<strong>支持启动。Linux 及其分支（OpenWRT、pfSense、OPNsense）可启动；Windows 需使用 <code>WinToGo</code></strong></li><li><strong>散热：</strong> 主动散热。<strong>2023 年后已全面升级为铜管散热器与滚静音风扇</strong></li><li><strong>电源：</strong> 标配 12V 2.5A 30W DC 电源，<strong>包含 DC 圆头转 USB-C 口直通线</strong></li><li><strong>尺寸：</strong> 7.5 x 7.5 x 4.8cm（<strong>方寸之间，尽享乐趣</strong>）</li></ul><blockquote><p><strong>注意：</strong> 特殊定制 C 口 12V DC 电源仅适用于 R1。请勿使用该电源给其他设备供电，以免烧坏其他电子设备。</p></blockquote><h2>结构设计</h2><p><img src="https://s2.loli.net/2023/03/19/EwsZmybJ2Og56xT.png" alt="R1 结构设计"></p><p><img src="https://s2.loli.net/2023/03/18/dqBHfG9aSomIb8w.png" alt="R1 内部结构"></p><p><img src="https://s2.loli.net/2023/03/18/SNbRW7GtLgYxJ3f.png" alt="R1 结构细节"></p><p><img src="https://s2.loli.net/2023/03/18/SGEr9LewCYRvkmP.png" alt="R1 尺寸"></p><p><img src="https://s2.loli.net/2023/03/18/ZMN7LtJoKlAU2TF.png" alt="R1 爆炸图"></p><h2>系统兼容性</h2><table><thead><tr><th>系统</th><th>系统</th><th>系统</th><th>系统</th><th>系统</th><th>系统</th></tr></thead><tbody><tr><td><img src="https://www.ikoolcore.com/cdn/shop/files/pfsense.webp?v=1704086584&amp;width=200" alt="pfSense"></td><td><img src="https://www.ikoolcore.com/cdn/shop/files/OPNsense.webp?v=1704086651&amp;width=200" alt="OPNsense"></td><td><img src="https://www.ikoolcore.com/cdn/shop/files/openwrt.webp?v=1704085927&amp;width=200" alt="OpenWrt"></td><td><img src="https://www.ikoolcore.com/cdn/shop/files/untangle-v.webp?v=1704086344&amp;width=200" alt="Untangle"></td><td><img src="https://www.ikoolcore.com/cdn/shop/files/XCP-NG.webp?v=1704086432&amp;width=200" alt="XCP-ng"></td><td><img src="https://www.ikoolcore.com/cdn/shop/files/panabit.webp?v=1704085395&amp;width=200" alt="Panabit"></td></tr><tr><td><img src="https://www.ikoolcore.com/cdn/shop/files/Ubuntu.webp?v=1704085681&amp;width=200" alt="Ubuntu"></td><td><img src="https://www.ikoolcore.com/cdn/shop/files/debian.webp?v=1704085608&amp;width=200" alt="Debian"></td><td><img src="https://www.ikoolcore.com/cdn/shop/files/centos_1.webp?v=1704085524&amp;width=200" alt="CentOS"></td><td><img src="https://www.ikoolcore.com/cdn/shop/files/windows_640.webp?v=1704096884&amp;width=200" alt="Windows"></td><td><img src="https://www.ikoolcore.com/cdn/shop/files/Proxmox-VE-logo.webp?v=1704084451&amp;width=200" alt="Proxmox VE"></td><td><img src="https://www.ikoolcore.com/cdn/shop/files/VMware.webp?v=1704086716&amp;width=200" alt="VMware"></td></tr></tbody></table><h2>常见问题</h2><h3>如何进入 R1 的 BIOS 后台？</h3><p>通电开机后，在 0.5 秒内按下 <code>F2</code> 即可进入 BIOS 后台；在 0.5 秒内按下 <code>F12</code> 即可进入启动项选择界面。</p><h3>如何设置来电自启和手动开关机？</h3><p>通电开机后的 0.5 秒内按下 <code>F2</code> 进入 BIOS，然后依次进入 <code>Chipset</code> → <code>PCH-IO Configuration</code> → <code>State After G3</code>。选择 <code>S0 State</code> 可设置来电自启，选择 <code>S5 State</code> 可设置为手动开关机。</p><h3>如何解锁温度墙？</h3><p>通电开机后的 0.5 秒内按下 <code>F2</code> 进入 BIOS，然后依次进入 <code>Advanced</code> → <code>Thermal Configuration</code> → <code>CPU Thermal Configuration</code> → <code>Tcc Activation Offset</code>，并调整数值。</p><p>默认值为 30，表示温度墙为 105 − 30 = 75°C。设置为 0 表示温度为 105°C 时触发温度墙；建议设置为 15，即温度墙为 105 − 15 = 90°C。如果自行提高温度墙上限，可能导致整机温度升高，请确认能够接受相关影响。</p><blockquote><p>硬酷科技在环境温度为 65°C 的高温压力测试环境中对 R1 进行了测试。处理器温度达到 90°C 以上时设备没有死机，并最终通过降频完成测试。</p></blockquote><h3>R1 的硬盘支持 NVMe 和 SATA 自适应吗？</h3><p>目前只能在 NVMe 和 SATA 中二选一，默认使用 NVMe 协议。如果希望使用发热较低、速度稍低的 SATA 协议 M.2 2242 硬盘，需要参考“升级 BIOS”页面刷写 SATA 协议 BIOS。从 SATA 协议 BIOS 切回 NVMe 协议 BIOS 时同样需要重新刷写。</p><blockquote><p><strong>警告：</strong> 刷写 BIOS 属于高风险操作，请自行承担相关风险。</p></blockquote><h3>如何给 R1 刷写 BIOS？</h3><p>请参考“升级 BIOS”页面中的操作说明。</p><h3>R1 支持传统的引导方式吗？</h3><p>不支持。Intel 第 10 代以后的处理器仅支持 UEFI 引导，不支持传统 BIOS。Panabit 等传统系统可以通过 PVE 或 ESXi 等虚拟化平台运行。</p><h3>R1 的 TF 卡支持引导启动吗？</h3><p>支持。Linux 及其分支（OpenWRT、pfSense、OPNsense）可以直接从 TF 卡启动。Windows 需要使用 <a href="https://rufus.ie/downloads/">Rufus</a> 写入 <code>WinToGo</code> 启动盘。</p><h3>R1 的电源规格是什么？</h3><p>R1 带有 PD 标识的 Type-C 接口支持 DC 12V/20V 和 PD 双协议，优先协商 20V，其次协商 12V。由于采用双供电协议，R1 没有使用传统 DC 圆头接口。所有订单均标配 DC 母头转 Type-C 公头的转接线，因此可以使用已有的 DC 12V 圆头电源为 R1 供电。</p>',34),c=[p],a={__name:"r1",setup(i,{expose:t}){return t({frontmatter:{}}),(d,l)=>(o(),e("div",n,c))}};export{a as default};
